            if tag == 'table':
                self.table_depth -= 1
                if self.table_depth == 0:
                    self.in_table = False
            elif tag in ['tr', 'td', 'th']:
                if tag == 'td':
                    self.in_cell = False
                if tag == 'tr':
                    self.in_row = False
            elif tag in ['ul', 'ol']:
                self.list_depth -= 1
                if self.list_depth == 0:
                    self.in_list = False
            elif tag == 'li':
                self.in_cell = False

    def handle_data(self, data):
        if self.in_discography and (self.in_cell or self.in_table or self.in_list):
